create table cage_user (id bigint generated by default as identity primary key, version bigint not null default 0, username varchar(255) not null unique, password varchar(255), display_name varchar(255), roles varchar(255), enabled boolean not null);

create table property (id bigint generated by default as identity primary key, version bigint not null default 0, name varchar(255), zone varchar(255), cutoff varchar(255), reporting_scope varchar(255), contact varchar(255));

create table patron (id bigint generated by default as identity primary key, version bigint not null default 0, legal_name varchar(255), alias_name varchar(255), date_of_birth date, address varchar(255), country varchar(255), contact varchar(255), occupation varchar(255), loyalty_id varchar(255) unique, tin text, identity_number text, identity_type varchar(255), issuing_authority varchar(255), identity_expiry date, identity_status varchar(255), residency varchar(255), w9status varchar(255), merged_into_id bigint references patron(id), temporary boolean not null);

create table transaction_type (id bigint generated by default as identity primary key, version bigint not null default 0, code varchar(255) unique, label varchar(255), treatment varchar(255), required_field varchar(255), tax_game varchar(255), active boolean not null, state varchar(255), created_by varchar(255), approved_by varchar(255), effective_from date, effective_to date);

create table cage_transaction (id bigint generated by default as identity primary key, version bigint not null default 0, source_id varchar(255) not null unique, patron_id bigint not null references patron(id), conductor_id bigint references patron(id), relationship varchar(255), type_id bigint not null references transaction_type(id), type_label varchar(255), treatment varchar(255), type_version bigint not null, gross numeric(38,2), cash numeric(38,2), cash_in numeric(38,2), cash_out numeric(38,2), currency varchar(255), exchange_rate numeric(38,2), occurred_at timestamptz, gaming_day date, property_zone varchar(255), gaming_cutoff varchar(255), rule_version bigint not null, station varchar(255), cashier varchar(255), reference varchar(255), notes varchar(255), status varchar(255), corrects_id bigint references cage_transaction(id), created_at timestamptz);

create table report (id bigint generated by default as identity primary key, version bigint not null default 0, kind varchar(255), group_key varchar(255), patron_id bigint not null references patron(id), gaming_day date, cash_in numeric(38,2), cash_out numeric(38,2), amount numeric(38,2), form_type varchar(255), game varchar(255), tax_rule_version varchar(255), withholding numeric(38,2), status varchar(255), external_outcome varchar(255), filing_status varchar(255), creator varchar(255), approver varchar(255), revision integer not null, approved_revision integer, due_date date, detection_date date, activity_start date, activity_end date, narrative text, category varchar(255), filing_type varchar(255), fields text, snapshot text, obligation_open boolean not null, updated_at timestamptz, external_id varchar(255), corrects_id bigint references report(id), unique(kind,group_key));

create table report_revision (id bigint generated by default as identity primary key, version bigint not null default 0, report_id bigint not null references report(id), revision integer not null, snapshot text, actor varchar(255), reason varchar(255), created_at timestamptz);

create table filing_batch (id bigint generated by default as identity primary key, version bigint not null default 0, kind varchar(255), creator varchar(255), status varchar(255), scenario varchar(255), checksum varchar(255), schema_version varchar(255), transport_receipt varchar(255), created_at timestamptz, submitted_at timestamptz, responded_at timestamptz, raw_response text);

create table batch_item (id bigint generated by default as identity primary key, version bigint not null default 0, batch_id bigint not null references filing_batch(id), report_id bigint not null references report(id), revision integer not null, snapshot text, outcome varchar(255), external_id varchar(255), message varchar(255), unique(report_id,revision));

create table audit_event (id bigint generated by default as identity primary key, version bigint not null default 0, scope varchar(255), entity_type varchar(255), entity_id bigint, action varchar(255), actor varchar(255), occurred_at timestamptz, correlation_id varchar(255), reason text, before_value text, after_value text);

create table work_task (id bigint generated by default as identity primary key, version bigint not null default 0, scope varchar(255), title varchar(255), report_id bigint, resolved boolean not null, resolution varchar(255), created_at timestamptz);

create table configuration (id bigint generated by default as identity primary key, version bigint not null default 0, code varchar(255) unique, payload text, reason varchar(255), changed_by varchar(255));

create table outbox_event (id bigint generated by default as identity primary key, version bigint not null default 0, aggregate_id bigint, payload text, published_at timestamptz, created_at timestamptz, attempts integer not null);
create index ix_tx_patron_day on cage_transaction(patron_id,gaming_day,status);
create index ix_patron_name on patron(lower(legal_name));
create index ix_report_queue on report(kind,status,due_date);
create index ix_audit_record on audit_event(entity_type,entity_id,occurred_at);
create index ix_outbox_pending on outbox_event(published_at,id);
-- Application role never mutates audit events. DB trigger also rejects update/delete.
create function immutable_audit() returns trigger language plpgsql as $$ begin raise exception 'Audit events are append only'; end; $$;
create trigger audit_append_only before update or delete on audit_event for each row execute function immutable_audit();
